    ]
  },
  "claims": [
    {
      "text": "Mindfulness lacks a universally accepted technical definition, so empirical findings require careful specification of the mental states, practices, and interventions under study.",
      "short_title": "Mindfulness lacks shared definition",
      "evidence_excerpts": [
        "There is neither one universally accepted technical definition of mindfulness nor any broad agreement about detailed aspects of the underlying concept to which it refers."
      ]
    },
    {
      "text": "Undifferentiated use of mindfulness and meditation can make brief app exercises, intensive retreats, questionnaires, and long-term practice appear falsely comparable.",
      "short_title": "Umbrella labels distort comparison",
      "evidence_excerpts": [
        "With current use of umbrella terms, a 5-minute meditation exercise from a popular phone application might be treated the same as a 3-month meditation retreat, and a self-report questionnaire might be equated with decades of meditation practice."
      ]
    },
    {
      "text": "Existing mindfulness self-report measures have unresolved construct-validity limits and may not track exactly what practice teaches.",
      "short_title": "Self reports remain uncertain",
      "evidence_excerpts": [
        "Although some self-report questionnaire measures of mindfulness seem to be effective in revealing particular mental and physical changes associated with practicing mindfulness, how closely these measures track exactly what is taught during practice remains unclear."
      ]
    },
    {
      "text": "Research on mindfulness should shift from seeking one unitary mindfulness measure toward measuring specific biological, emotional, cognitive, behavioral, and social functions changed by training.",
      "short_title": "Specific functions should replace unity",
      "evidence_excerpts": [
        "Scientific research on the aggregate of mental states labeled by mindfulness would benefit from redirecting attempts to directly measure mindfulness toward measuring supporting mental faculties."
      ]
    },
    {
      "text": "The clinical evidence base for mindfulness-based interventions is too immature to justify broad real-world implementation without stronger controls and later-stage research.",
      "short_title": "Clinical evidence remains immature",
      "evidence_excerpts": [
        "Only 30% of research using mindfulness-based interventions has moved beyond Stage 1; 9% of the total has been conducted at Stage 2b, and only 1% has been conducted outside research contexts."
      ]
    },
    {
      "text": "Mindfulness-based interventions show a mixed pattern of moderate, low, or absent efficacy depending on outcome and disorder.",
      "short_title": "Efficacy is mixed",
      "evidence_excerpts": [
        "Compared to active controls, MBIs were found to have a mixture of only moderate, low, or no efficacy depending on the disorder being treated."
      ]
    },
    {
      "text": "Mindfulness-based interventions vary substantially in content, delivery, instructor training, homework, and participant population, limiting broad efficacy claims across interventions.",
      "short_title": "Interventions vary substantially",
      "evidence_excerpts": [
        "The varieties of interventions labeled as mindful differ in content, meeting type and frequency, instructions, homework, readings, instructor or therapist training, and accessibility."
      ]
    },
    {
      "text": "Meditation can be associated with clinically significant adverse experiences, and assumptions of minimal adverse effects rest more on lack of research than substantive evidence.",
      "short_title": "Meditation can harm",
      "evidence_excerpts": [
        "Meditation-related experiences serious or distressing enough to warrant additional treatment or medical attention have been reported in more than 20 published case reports or observational studies."
      ]
    },
    {
      "text": "Adverse-event assessment in meditation research needs active monitoring, rigorous trial designs, and clinical interviews rather than passive safety assumptions.",
      "short_title": "Adverse events need monitoring",
      "evidence_excerpts": [
        "Most current methods for assessing adverse effects in meditation-related research are insufficient to produce an accurate estimate; some MBI researchers have started to actively monitor adverse events through questionnaires or clinician interviews."
      ]
    },
    {
      "text": "Neuroimaging findings about mindfulness are preliminary and vulnerable to oversimplification, group-level confounding, physical artifacts, and unclear practical significance.",
      "short_title": "Brain findings stay preliminary",
      "evidence_excerpts": [
        "Representative pictures from fMRI and other neuroimaging methods do not clearly convey the complex chain of biological and computational steps that lead to inferences about changes in brain structure and function."
      ]
    },
    {
      "text": "Future mindfulness science should emphasize preregistration, open-science replications, stronger clinical controls, adverse-event warnings, and modest communication of neuroimaging results.",
      "short_title": "Future science needs rigor",
      "evidence_excerpts": [
        "Future studies of mindfulness should conform to lessons from the replication crisis, including preregistered experiments and open-science replications, while clinical applications should seek more uniformity and better control."
      ]
    }
  ],
  "evidence_items": [
    {
      "evidence_id": "evidence-growth-in-mindfulness-coverage--a1f4c8d29e73",
      "title": "Growth In Mindfulness Coverage",
      "excerpt": "Fig. 1. Scientific and news media articles on mindfulness and/or meditation by year from 1970 to 2015. Empirical scientific articles with the term mindfulness or meditation in the abstract, title, or keywords were searched using Scopus; media pieces with the term mindfulness or meditation were searched using LexisNexis.",
      "overview": "The figure operationalizes the article's claim that mindfulness became a rapidly expanding scientific and media topic. It does not prove hype by itself, but it documents the growth context in which public exaggeration, inconsistent terminology, and pressure for clinical uptake became consequential.",
      "evidence_type": "figure_result",
      "claim_refs": [
