      ],
      "source_id": "source-04-mind-the-hype-a-critical-evaluation-and-prescriptive-agenda-for-research-on-mind-w2761197918--79c0d54db997",
      "page_refs": [
        "Table 1",
        "p.39"
      ]
    },
    {
      "evidence_id": "evidence-clinical-stage-distribution--c9a4e2b51d08",
      "title": "Clinical Stage Distribution",
      "excerpt": "Dimidjian and Segal estimate, using the NIH stage model, that only 30% of research using mindfulness-based interventions has moved beyond Stage 1; the majority beyond Stage 1 has been conducted at Stage 2a, only 9% of the total at Stage 2b with active controls, and only 1% outside research contexts.",
      "overview": "These percentages anchor the article's clinical caution. They show that much MBI research remains early-stage or weakly controlled, with very little evidence from ordinary clinical settings, making broad implementation claims premature even where some efficacy signals exist.",
      "evidence_type": "statistical_result",
      "claim_refs": [
        "4",
        "10"
      ],
      "source_id": "source-04-mind-the-hype-a-critical-evaluation-and-prescriptive-agenda-for-research-on-mind-w2761197918--79c0d54db997",
      "page_refs": [
        "p.45"
      ]
    },
    {
      "evidence_id": "evidence-active-control-efficacy-mix--d6e8b3904a77",
      "title": "Active Control Efficacy Mix",
      "excerpt": "A review and meta-analysis commissioned by the U.S. Agency for Healthcare Research and Quality found that, compared to active controls, MBIs had only moderate efficacy for anxiety, depression, and pain, low efficacy for stress and quality of life, and no effect or insufficient evidence for attention, positive mood, substance abuse, eating habits, sleep, and weight control.",
      "overview": "This statistical synthesis supports the article's distinction between selective promise and broad therapeutic overclaiming. It establishes that efficacy depends on the target outcome, comparator, and condition rather than extending uniformly across advertised uses.",
      "evidence_type": "statistical_result",
      "claim_refs": [
        "5"
      ],
      "source_id": "source-04-mind-the-hype-a-critical-evaluation-and-prescriptive-agenda-for-research-on-mind-w2761197918--79c0d54db997",
      "page_refs": [
        "p.46"
      ]
    },
    {
      "evidence_id": "evidence-mbsr-intervention-dose--e3c72a91b5df",
      "title": "MBSR Intervention Dose",
      "excerpt": "The gold-standard model of MBSR is an 8-week course involving 20 to 26 hours of formal meditation training during eight weekly group classes of 1.5 to 2.5 hours, one all-day 6-hour class, and home practice of about 45 minutes per day, 6 days per week; brief adaptations may involve as few as four 20-minute sessions.",
      "overview": "This protocol description makes the intervention-heterogeneity problem auditable. When studies label both intensive MBSR and very brief training as mindfulness-based, pooled conclusions can obscure dose, content, and delivery differences that matter for efficacy and safety.",
      "evidence_type": "model_constraint",
      "claim_refs": [
        "1",
        "6"
      ],
      "source_id": "source-04-mind-the-hype-a-critical-evaluation-and-prescriptive-agenda-for-research-on-mind-w2761197918--79c0d54db997",
      "page_refs": [
        "p.45"
      ]
    },
    {
      "evidence_id": "evidence-meditation-adverse-cases--f0b6a18c4e2d",
      "title": "Meditation Adverse Cases",
      "excerpt": "Meditation-related experiences serious or distressing enough to warrant additional treatment or medical attention have been reported in more than 20 published case reports or observational studies, documenting psychosis, mania, depersonalization, anxiety, panic, traumatic-memory reexperiencing, and other clinical deterioration.",
      "overview": "The evidence does not quantify incidence because many reports are case studies or observational studies without controls. It nevertheless refutes the assumption that meditation is always benign and motivates prospective adverse-event measurement in trials and clinical programs.",
      "evidence_type": "observational_result",
      "claim_refs": [
        "7",
